  "бацам": "Значење: Облик глагола бацати; ја бацам.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "бацао": "Значење: Облик глагола бацати у прошлом времену.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "бацач": "Значење: Онај који баца предмет, лопту или оруђе.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "бацаш": "Значење: Облик глагола бацати; ти бацаш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
