  "бацим": "Значење: Облик глагола бацити; да нешто хитнем или одложим.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "бацио": "Значење: Облик глагола бацити у прошлом времену.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "бациш": "Значење: Облик глагола бацити; ти бациш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
