  "бачен": "Значење: Мушки облик речи бачен; онај који је бачен.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "башта": "Значење: Ограђен или уређен простор за цвеће, поврће или одмор.\n\nГраматика: Именица; генитив; јединина.",
