  "бдење": "Значење: Остајање будним; ноћно чување, молитва или пажљиво праћење.\n\nГраматика: Именица; номинатив; множина.",
  "бебин": "Значење: Онај који припада беби.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
