  "бегај": "Значење: Заповедни облик глагола бегати; склони се или трчи одатле.\n\nГраматика: Глагол; заповедни мод (императив).",
  "бедак": "Значење: Разговорно: лоша ситуација, непријатност или туга.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
