  "белег": "Значење: Ознака, траг, ожиљак или знак по коме се нешто памти.\n\nГраматика: Именица; генитив.",
  "белим": "Значење: Падежни или глаголски облик речи бео/белити.\n\nГраматика: Именица; инструментал.",
