  "бенџо": "Значење: Жичани музички инструмент округлог тела.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "берба": "Значење: Сакупљање плодова, најчешће грожђа, воћа или поврћа.\n\nГраматика: Именица; генитив; јединина.",
  "бербе": "Значење: Множина или падежни облик речи берба.\n\nГраматика: Именица; номинатив; множина.",
  "берза": "Значење: Тржиште на ком се купују и продају хартије од вредности, роба или валуте.\n\nГраматика: Именица; генитив; јединина.",
  "берзе": "Значење: Множина или падежни облик речи берза.\n\nГраматика: Именица; номинатив; множина.",
