  "бесан": "Значење: Љут, разгневљен; може значити и заражен беснилом.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "бесна": "Значење: Женски облик речи бесан.\n\nГраматика: Именица; генитив; јединина.",
