  "бизон": "Значење: Крупна дивља животиња слична биволу.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "бијем": "Значење: Облик глагола бити у значењу ударати; ја бијем.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "билом": "Значење: Падежни облик придева бео или облика био, зависно од употребе.\n\nГраматика: Именица; инструментал.",
  "биљка": "Значење: Живо биће које расте из земље и храни се светлошћу.\n\nГраматика: Именица; генитив; јединина.",
  "биљке": "Значење: Множина или падежни облик речи биљка.\n\nГраматика: Именица; номинатив; множина.",
