  "бирао": "Значење: Облик глагола бирати у прошлом времену.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "бираш": "Значење: Облик глагола бирати; ти бираш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
  "бироа": "Значење: Облик речи биро; канцеларија, служба или радни сто.\n\nГраматика: Именица; генитив; јединина.",
