  "бићем": "Значење: Облик глагола бити; ја ћу бити.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "бићеш": "Значење: Облик глагола бити; ти ћеш бити.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
  "бичем": "Значење: Падежни облик речи бич; предметом за ударање или терање.\n\nГраматика: Именица; инструментал.",
  "блага": "Значење: Женски облик речи благ; нежна, умерена или пријатна.\n\nГраматика: Именица; генитив; јединина.",
  "благе": "Значење: Множина или падежни облик речи благ.\n\nГраматика: Именица; номинатив; множина.",
  "благи": "Значење: Онај који је нежан, умерен или није оштар.\n\nГраматика: Придev; мушки род; номинатив; множина.",
  "благо": "Значење: Нешто драгоцено; може значити и нежно, тихо или умерено.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "благу": "Значење: Падежни облик придева благ.\n\nГраматика: Именица; акузатив.",
  "блажи": "Значење: Упоредни облик придева благ; мање оштар или нежнији.\n\nГраматика: Именица; номинativ; множина.",
  "блата": "Значење: Облик речи блато; мокра земља или каљуга.\n\nГраматика: Именица; генитив; јединина.",
  "блато": "Значење: Мешавина земље и воде; каљуга.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
