  "једне": "Значење: Облик речи један; једне особе, ствари или појаве.\n\nГраматика: Именица; номинатив; множина.",
  "једни": "Значење: Облик речи један; неки, поједини или једни од више.\n\nГраматика: Именица; номинатив; множина.",
  "једно": "Значење: Средњи облик броја један.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "једну": "Значење: Женски облик броја један у акузативу.\n\nГраматика: Именица; датив.",
  "једра": "Значење: Множина речи једро; платна која покрећу брод ветром.\n\nГраматика: Именица; множина.",
  "једро": "Значење: Платно на броду које хвата ветар; може значити и снажно, пуно.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "јежим": "Значење: Облик глагола јежити се; осећам дрхтај, страх или нелагоду.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "језив": "Значење: Страшан, непријатан или узнемирујућ.\n\nГраматика: Придev; мушки род; номинатив; јединина.",
  "језик": "Значење: Орган у устима; систем речи којим људи говоре.\n\nГраматика: Именица; номинатив; јединина.",
  "јелда": "Значење: Разговорна узречица за тражење потврде; значи зар не.\n\nГраматика: Именица; генитив; јединина.",
  "јелен": "Значење: Шумска животиња са роговима код мужјака.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "јелка": "Значење: Зимзелено дрво; често се украшава за празнике.\n\nГраматика: Именица; номинатив; јединина.",
  "јелке": "Значење: Облик речи јелка; зимзелена дрвета.\n\nГраматика: Именица; номинатив; множина.",
  "јелку": "Значење: Облик речи јелка; зимзелено дрво.\n\nГраматика: Именица; акузатив.",
  "јелом": "Значење: Облик речи јело; храном или оброком.\n\nГраматика: Именица; инструментал.",
  "јесам": "Значење: Потврдни облик глагола бити у првом лицу једнине.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "јесен": "Значење: Годишње доба између лета и зиме.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "јесмо": "Значење: Облик глагола бити; ми јесмо.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "јесте": "Значење: Потврдни облик глагола бити или одговор који значи да.\n\nГраматика: Именица; номинатив; множина.",
  "јести": "Значење: Уносити храну у тело.\n\nГраматика: Именица; номинativ; множина.",
  "јетра": "Значење: Унутрашњи орган који прерађује материје у телу.\n\nГраматика: Именица; генитив; јединина.",
  "јетре": "Значење: Множина или падежни облик речи јетра.\n\nГраматика: Именица; номинатив; множина.",
  "јетри": "Значење: Облик речи јетра; органу који учествује у преради материја у телу.\n\nГраматика: Именица; номинатив; множина.",
  "јетру": "Значење: Облик речи јетра; важан унутрашњи орган.\n\nГраматика: Именица; датив.",
  "јечам": "Значење: Житарица која се користи за храну, сточну храну и производњу слада.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
