  "љутио": "Значење: Облик глагола љутити; он је љутио.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "љутих": "Значење: Облик речи љут; оних који су бесни или оштрог укуса.\n\nГраматика: Именица; генитив; множина.",
