  "потоп": "Значење: Велика поплава или потпуно плављење.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "поука": "Значење: Корисан закључак или лекција.\n\nГраматика: Именица; генитив; јединина.",
