  "поход": "Значење: Организован одлазак, војни или свечани пут.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "почев": "Значење: Почевши од; од неког тренутка или места.\n\nГраматика: Именица; номинатив; јединина.",
  "почео": "Значење: Облик глагола почети; он је започео.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "почет": "Значење: Започет; онај који је почео.\n\nГраматика: Именица; номинатив; јединина.",
  "почне": "Значење: Облик глагола почети; он или она започне.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "почни": "Значење: Заповедни облик глагола почети; започни.\n\nГраматика: Глагол; заповедни мод (императив).",
  "почну": "Значење: Облик глагола почети; они започну.\n\nГраматика: Глагол; облик.",
  "пошао": "Значење: Облик глагола поћи; он је кренуо.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "пошла": "Значење: Облик глагола поћи; она је кренула.\n\nГраматика: Глагол; облик.",
  "пошли": "Значење: Облик глагола поћи; они су кренули.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
  "пошло": "Значење: Облик глагола поћи; нешто је кренуло.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "пошта": "Значење: Установа за слање писама и пакета.\n\nГраматика: Именица; генитив; јединина.",
  "поште": "Значење: Облик речи пошта; установе или пошиљке.\n\nГраматика: Именица; номинатив; множина.",
  "пошти": "Значење: Облик речи пошта; установи за пошиљке.\n\nГраматика: Именица; номинатив; множина.",
  "пошто": "Значење: Везник који значи јер или након што.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "пошту": "Значење: Пошта; установа или пошиљке које се шаљу.\n\nГраматика: Именица; акузатив.",
  "права": "Значење: Облик речи право или придева прав; исправна или законска.\n\nГраматика: Именица; генитив; јединина.",
  "праве": "Значење: Облик придева прав или глагола правити.\n\nГраматика: Придев; средњи род; номинатив; множина.",
  "прави": "Значење: Исправан, истински или онај који нешто прави.\n\nГраматика: Придev; мушки род; номинатив; множина.",
  "право": "Значење: Законско овлашћење, смер без скретања или исправно.\n\nГраматика: Прилог.",
  "праву": "Значење: Облик речи право или придева прав.\n\nГраматика: Именица; датив.",
  "прага": "Значење: Облик речи праг; доње граничне летве или границе.\n\nГраматика: Именица; генитив; јединина.",
  "прагу": "Значење: Облик речи праг; месту улаза или граници.\n\nГраматика: Именица; акузатив.",
  "прала": "Значење: Облик глагола прати; она је прала.\n\nГраматика: Глагол; облик.",
  "прања": "Значење: Облик речи прање; чишћења водом.\n\nГраматика: Именица; генитив; јединина.",
  "прање": "Значење: Чишћење водом или другим средством.\n\nГраматика: Именица; номинатив; множина.",
  "прању": "Значење: Облик речи прање; чишћењу водом.\n\nГраматика: Именица; датив.",
  "прасе": "Значење: Младо свиње.\n\nГраматика: Именица; номинатив; множина.",
  "прате": "Значење: Облик глагола пратити; они иду уз некога или посматрају.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "прати": "Значење: Прати; иде уз некога или чисти водом, зависно од нагласка.\n\nГраматика: Именица; номинатив; множина.",
  "праха": "Значење: Облик речи прах; ситне суве материје.\n\nГраматика: Именица; генитив; јединина.",
  "праху": "Значење: Облик речи прах; ситној сувој материји.\n\nГраматика: Именица; датив.",
  "праши": "Значење: Облик глагола прашити; диже или уклања прашину.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
  "првак": "Значење: Најбољи у такмичењу или ученик првог разреда.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "првим": "Значење: Облик редног броја први.\n\nГраматика: Именица; инструментал.",
  "првог": "Значење: Облик редног броја први.\n\nГраматика: Именица; генитив.",
  "првој": "Значење: Облик редног броја први; оној која је прва.\n\nГраматика: Именица; датив; локатив.",
  "првом": "Значење: Облик редног броја први; оном који је први.\n\nГраматика: Именица; инструментал.",
  "пргав": "Значење: Нагле нарави, лако се љути.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "преда": "Значење: Облик глагола предати; он или она уручи или препусти.\n\nГраматика: Глагол; облик.",
  "преде": "Значење: Облик глагола прести или предети; мачка може да преде.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "преди": "Значење: Облик глагола прести; прави нит.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
