  "пређе": "Значење: Облик глагола прећи; он или она пређе.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "пређи": "Значење: Заповедни облик глагола прећи; пређи на другу страну.\n\nГраматика: Глагол; заповедни мод (императив).",
