  "прете": "Значење: Облик глагола претити; они најављују опасност.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "прети": "Значење: Облик глагола претити; он или она најављује опасност.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
  "прећи": "Значење: Прећи; доћи са једне стране на другу.\n\nГраматика: Именица; номинатив; множина.",
  "преци": "Значење: Преци; ранији чланови породице или народа.\n\nГраматика: Именица; номинатив; множина.",
