  "приђе": "Значење: Облик глагола прићи; он или она се приближи.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "приђи": "Значење: Заповедни облик глагола прићи; приближи се.\n\nГраматика: Глагол; заповедни мод (императив).",
