  "сајту": "Значење: Облик речи сајт; интернет страници.\n\nГраматика: Именица; акузатив.",
  "сакоа": "Значење: Облик речи сако; горњи део одела.\n\nГраматика: Именица; генитив; јединина.",
  "саком": "Значење: Облик речи сако; горњим делом одела.\n\nГраматика: Именица; инструментал.",
