  "сакри": "Значење: Облик глагола сакрити; склони да се не види.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
  "салаш": "Значење: Пољско имање са кућом и помоћним зградама.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
  "салио": "Значење: Облик глагола салити; он је излио или слио.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "салом": "Значење: Облик речи сала; просторијом за окупљање или масноћом, зависно од контекста.\n\nГраматика: Именица; инструментал.",
  "салон": "Значење: Већа просторија или радња за услуге.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "салса": "Значење: Плес и музички стил; може бити и зачињен сос.\n\nГраматика: Именица; генитив; јединина.",
  "салун": "Значење: Крчма или бар, најчешће у старом западњачком контексту.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "саман": "Значење: Необрађена цигла од земље и сламе.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "самар": "Значење: Опрема која се ставља на леђа товарне животиње.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "самац": "Значење: Особа која живи сама или није у браку.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "самим": "Значење: Облик придева сам; управо тим или њим самим.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "самит": "Значење: Састанак на највишем нивоу.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
