  "самог": "Значење: Облик придева сам; њега самог.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "самој": "Значење: Облик придева сам; њој самој.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
  "самом": "Значење: Облик придева сам; њему самом.\n\nГраматика: Придев; мушки род; номинатив; јединина.",
