  "сване": "Значење: Облик глагола сванути; почне дан.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "свари": "Значење: Облик глагола сварити; преради храну у организму.\n\nГраматика: Глагол; презент; 3. лице; јединина.",
  "свега": "Значење: Облик речи све; укупно или од свега.\n\nГраматика: Именица; генитив; јединина.",
  "свежа": "Значење: Женски облик придева свеж; нова, чиста или прохладна.\n\nГраматика: Именица; генитив; јединина.",
  "свеже": "Значење: Свеже; недавно, ново или прохладно.\n\nГраматика: Именица; номинатив; множина.",
