  "чудне": "Значење: Облик придева чудан; необичне.\n\nГраматика: Придев; средњи род; номинатив; множина.",
  "чудни": "Значење: Облик придева чудан; необични.\n\nГраматика: Придев; мушки род; номинатив; множина.",
