  "чујеш": "Значење: Облик глагола чути; ти чујеш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
  "чујмо": "Значење: Облик глагола чути; позив да чујемо.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "чујте": "Значење: Облик глагола чути; позив или наредба да слушате.\n\nГраматика: Глагол; презент; 3. лице; множина.",
  "чунак": "Значење: Мали чамац или део разбоја којим се провлачи нит.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
