  "џамбо": "Значење: Веома велик; позајмљени израз за нешто огромно.\n\nГраматика: Именица; номинатив; јединина; средњи род.",
  "џелат": "Значење: Онај који извршава смртну казну.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "џемом": "Значење: Облик речи џем; слатким намазом од воћа.\n\nГраматика: Именица; инструментал.",
  "џепни": "Значење: Који је намењен за џеп или је малог формата.\n\nГраматика: Именица; номинativ; множина.",
