  "џерси": "Значење: Острво Џерси или врста тканине/дреса.\n\nГраматика: Именица; номинativ; множина.",
  "џихад": "Значење: Верски појам борбе или настојања у исламу.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "џоинт": "Значење: Жаргонски назив за цигарету са канабисом.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
