  "шалим": "Значење: Облик глагола шалити се; ја се шалим.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "шалио": "Значење: Облик глагола шалити се; он се шалио.\n\nГраматика: Глагол; прошло време; L-облик; мушки род; јединина.",
  "шалиш": "Значење: Облик глагола шалити се; ти се шалиш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
  "шаљем": "Значење: Облик глагола слати; ја шаљем.\n\nГраматика: Глагол; презент; 1. лице; јединина.",
  "шаљеш": "Значење: Облик глагола слати; ти шаљеш.\n\nГраматика: Глагол; презент; 2. лице; јединина.",
