  "шанка": "Значење: Облик речи шанк; пулта у угоститељству.\n\nГраматика: Именица; генитив; јединина.",
  "шанку": "Значење: Облик речи шанк; пулту у угоститељству.\n\nГраматика: Именица; акузатив.",
