  "шашав": "Значење: Откачен, необичан, смешан.\n\nГраматика: Именица; номинатив; јединина; мушки род.",
  "шваба": "Значење: Разговорни назив за Немца; може бити погрдан, зависно од контекста.\n\nГраматика: Именица; генитив; јединина.",
  "швабе": "Значење: Множина или падежни облик речи шваба.\n\nГраматика: Именица; номинатив; множина.",
